import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.Bi388yPt.js";const T=JSON.parse('{"title":"扩展选型","description":"","frontmatter":{},"headers":[],"relativePath":"guide/extensions.md","filePath":"guide/extensions.md"}'),d={name:"guide/extensions.md"};function i(s,e,n,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="扩展选型" tabindex="-1">扩展选型 <a class="header-anchor" href="#扩展选型" aria-label="Permalink to &quot;扩展选型&quot;">​</a></h1><p>核心通过 Transport 接口执行 HTTP，不依赖具体执行器或状态库。扩展只消费 <code>@restmodel/restmodel</code> 公共入口。</p><table tabindex="0"><thead><tr><th>需求</th><th>入口</th><th>依赖与边界</th></tr></thead><tbody><tr><td>原生 Fetch</td><td>core 的 fetchTransport</td><td>核心内置，无额外运行依赖</td></tr><tr><td>复用 Axios</td><td>axios 的 axiosTransport</td><td>需要 Axios；拦截器与 defaults 由调用方管理</td></tr><tr><td>模拟 HTTP</td><td>mock 的 withMock</td><td>装饰 Transport，按最终 HTTP 请求匹配</td></tr><tr><td>共享请求状态</td><td>pinia 的 defineResourceStore</td><td>需要 Pinia、Vue；管理请求生命周期，不提供缓存</td></tr></tbody></table><p>各扩展均面向公共发布，目前尚未发布。工作区先执行 <code>pnpm install</code>、<code>pnpm build</code>；仓库外消费使用本地 tarball 并同时安装对应 peer，具体版本以各扩展 README 和 package.json 为准。</p><h2 id="axios" tabindex="-1">Axios <a class="header-anchor" href="#axios" aria-label="Permalink to &quot;Axios&quot;">​</a></h2><p>将客户端的 transport 设为 <code>axiosTransport(axios.create())</code>。非 2xx 响应由核心统一分类为 HTTP 错误，业务信封和分页仍由 scheme 处理。<a href="/RESTModel/extensions/axios">Axios 用法</a>。</p><h2 id="http-mock" tabindex="-1">HTTP Mock <a class="header-anchor" href="#http-mock" aria-label="Permalink to &quot;HTTP Mock&quot;">​</a></h2><p><code>withMock(realTransport, rules)</code> 根据最终 method、url、headers 和已编码 body 按顺序匹配。默认未命中报错；只有显式开启 passthrough 才访问真实网络。Mock 不验证实际服务或 CORS。<a href="/RESTModel/extensions/mock">HTTP Mock 用法</a>。</p><h2 id="pinia" tabindex="-1">Pinia <a class="header-anchor" href="#pinia" aria-label="Permalink to &quot;Pinia&quot;">​</a></h2><p>通过 loader 连接资源调用，将 signal 传给 <code>.with({ signal })</code>。Store 暴露 data/error/pending；run 采用最后一次调用生效，组件释放自己的订阅，最后一个订阅释放才取消共享请求。没有自动重试或缓存。<a href="/RESTModel/extensions/pinia">Pinia 用法</a>。</p><h2 id="自定义执行器" tabindex="-1">自定义执行器 <a class="header-anchor" href="#自定义执行器" aria-label="Permalink to &quot;自定义执行器&quot;">​</a></h2><p>Transport 接收准备和编码完成的 HttpRequest，返回 status、headers、body。非 2xx 也返回响应，让 core 分类。执行器应监听 signal 并释放自己的资源，不自动跟随重定向。更多约束见<a href="/RESTModel/reference/client">客户端与 HTTP 执行</a>。</p>',12)])])}const x=t(d,[["render",i]]);export{T as __pageData,x as default};
